<script lang="ts">
import {onMount,tick} from "svelte";
import {localCourseRequest} from "../lib/local-course";
import StudyPractice from "./StudyPractice.svelte";
import CourseAudio from "./CourseAudio.svelte";
import DictionaryText from "./DictionaryText.svelte";
import DictionaryPopover from "./DictionaryPopover.svelte";
import {courseReadingSupport,courseSentenceParts} from "../lib/course-reading-support";
import type {DictionaryLookupResponse} from "../lib/api-contracts";
import type {CourseAction,CourseActionResult,CourseLanguage,CourseProgress,CourseSentence,PublicCourseLesson} from "../../types/course";
let {route,onRouteChange}:{route:string;onRouteChange:(r:string)=>void}=$props();
type Summary=Pick<PublicCourseLesson,"id"|"day"|"title"|"language"|"estimatedMinutes">&{exerciseCount:number};
let catalog=$state<Summary[]>([]),records=$state<CourseProgress[]>([]),lesson=$state<PublicCourseLesson|null>(null),progress=$state<CourseProgress|null>(null);
let feedback=$state<Record<string,NonNullable<CourseActionResult["feedback"]>>>({});
let loading=$state(true),busy=$state(false),error=$state(""),notice=$state(""),mobileIndex=$state(false);
let language=$derived<CourseLanguage>(route.split("/")[0]==="ar-EG"?"ar-EG":"hu");
let selected=$derived(route.split("/")[1]??"");
let destination=$derived(["review","reference","settings"].includes(selected)?selected:"lessons");
let lessons=$derived(catalog.filter(l=>l.language===language).sort((a,b)=>a.day-b.day));
let arabic=$derived(language==="ar-EG");
let section=$state(0),inspector=$state(""),translations=$state<string[]>([]),transliteration=$state(false),inspected=$state(false),practiceStart=$state(0);
let resume=$state<Record<string,string>>({});let pane=$state<"read"|"pattern"|"practice"|"reread">("read");
let search=$state("");let references=$state<PublicCourseLesson[]>([]),referenceLoading=$state(false);
let referenceUsed=false;let request=0;let requestedExercise="";let referenceClose=$state<HTMLButtonElement|undefined>();let referenceTrigger:HTMLElement|undefined;
async function closeReference(){inspector="";await tick();const target=referenceTrigger?.isConnected?referenceTrigger:document.getElementById("study-content");target?.focus({preventScroll:true});}
let dictionaryEntry=$state<{term:string;headword:string;lookup:DictionaryLookupResponse|null;contextMeaning:string;anchor:HTMLElement}|null>(null);
async function openReadingDictionary(entry:NonNullable<typeof dictionaryEntry>){
 if(!entry.anchor.closest(".inspector"))referenceTrigger=entry.anchor;dictionaryEntry=entry;inspector="dictionary";support();
 await tick();referenceClose?.focus({preventScroll:true});
}
let reading=$derived(lesson?.readings[section]);
let word=$derived(lesson?.vocabulary.find(w=>w.id===inspector));
let concept=$derived(lesson?.concepts.find(c=>c.id===inspector));
let attempts=$derived(Object.values(progress?.exercises??{}).flatMap(e=>e.attempts));
let completedExercises=$derived(Object.values(progress?.exercises??{}).filter(e=>e.attempts.length).length);
let difficult=$derived(records.filter(p=>p.language===language).flatMap(p=>Object.entries(p.exercises).filter(([,s])=>s.attempts.length && s.attempts.at(-1)?.correct===false).map(([id,s])=>({lessonId:p.lesson_id,id,at:s.attempts.at(-1)!.at,title:catalog.find(l=>l.id===p.lesson_id)?.title??p.lesson_id}))));
let referenceWords=$derived([...new Map(references.filter(l=>l.language===language).flatMap(l=>l.vocabulary.map(w=>[w.id,{...w,lessonId:l.id}] as const))).values()].filter(w=>`${w.term} ${w.english} ${w.transliteration??""}`.toLocaleLowerCase().includes(search.toLocaleLowerCase())));
const localPrefix="langouste-course-local:v1:";
function label(l:CourseLanguage){return l==="hu"?"Hungarian":"Egyptian Arabic";}
function go(id=""){mobileIndex=false;onRouteChange(`${language}${id?`/${id}`:""}`);}
function support(){inspected=true;try{sessionStorage.setItem(`langouste-study-support:${lesson?.id}`,"1");}catch{ /* Evidence stays conservative for this session. */ }}
function reveal(id:string){if(translations.includes(id))translations=translations.filter(x=>x!==id);else{translations=[...translations,id];support();}}
function switchLanguage(l:CourseLanguage){mobileIndex=false;onRouteChange(`${l}${resume[l]?`/${resume[l]}`:""}`);}
function savePosition(exercise?:number){if(!lesson)return;try{const key=`langouste-workbook-position:v1:${lesson.id}`;const prior=JSON.parse(localStorage.getItem(key)??"{}");localStorage.setItem(key,JSON.stringify({...prior,pane,section,...(exercise!==undefined?{exercise}:{})}));}catch{notice="Your activity is saved, but this browser could not save your place.";}}
function storeResume(id:string){resume={...resume,[language]:id};try{localStorage.setItem("langouste-workbook-resume:v1",JSON.stringify(resume));}catch{notice="This browser could not save your place. Lesson records have not been changed.";}}
onMount(async()=>{try{resume=JSON.parse(localStorage.getItem("langouste-workbook-resume:v1")??"{}");}catch{resume={};}try{const data=await localCourseRequest<{lessons:Summary[];progress:CourseProgress[]}>("/course");catalog=data.lessons;records=data.progress;}catch(e){error=e instanceof Error?e.message:"Could not load lessons.";}finally{loading=false;}});
$effect(()=>{const id=selected;const lang=language;const n=++request;lesson=null;progress=null;feedback={};inspector="";translations=[];section=0;error="";inspected=false;transliteration=false;
if(!id||["review","reference","settings"].includes(id)){loading=false;return;}
loading=true;localCourseRequest<{lesson:PublicCourseLesson;progress:CourseProgress;feedback:typeof feedback}>(`/course/${id}`).then(data=>{if(n!==request)return;if(data.lesson.language!==lang){error="This lesson belongs to the other language. Choose it in the lesson list.";return;}lesson=data.lesson;progress=data.progress;feedback=data.feedback;pane=data.progress.step==="practice"?"practice":data.progress.step==="grammar"?"pattern":"read";
const next=data.lesson.exercises.findIndex(e=>e.id===requestedExercise);practiceStart=next>=0?next:Math.max(0,data.lesson.exercises.findIndex(e=>!data.progress.exercises[e.id]?.attempts.length));if(next>=0)pane="practice";requestedExercise="";
section=Math.max(0,data.lesson.readings.findIndex(r=>!data.progress.read_sections.includes(r.id)));
try{const position=JSON.parse(localStorage.getItem(`langouste-workbook-position:v1:${id}`)??"{}");if(Number.isInteger(position.section)&&position.section>=0&&position.section<data.lesson.readings.length)section=position.section;if(next<0){if(Number.isInteger(position.exercise)&&position.exercise>=0&&position.exercise<data.lesson.exercises.length)practiceStart=position.exercise;if(["read","pattern","practice","reread"].includes(position.pane))pane=position.pane;}}catch{/* Existing lesson records remain untouched. */}
try{inspected=referenceUsed||sessionStorage.getItem("langouste-workbook-reference-support:v1")==="1"||sessionStorage.getItem(`langouste-study-support:${id}`)==="1";}catch{inspected=true;}
if(pane==="pattern")support();storeResume(id);
}).catch(e=>{if(n===request)error=e.message;}).finally(()=>{if(n===request)loading=false;});});
$effect(()=>{if(destination!=="reference"||!catalog.length)return;const n=request;referenceLoading=true;Promise.all(catalog.filter(l=>l.language===language).map(l=>localCourseRequest<{lesson:PublicCourseLesson}>(`/course/${l.id}`).then(d=>d.lesson))).then(data=>{if(n===request){references=data;referenceUsed=true;try{sessionStorage.setItem("langouste-workbook-reference-support:v1","1");}catch{/* The in-memory flag keeps this session conservative. */}}}).catch(e=>{if(n===request)error=e.message;}).finally(()=>{if(n===request)referenceLoading=false;});});
async function act(action:CourseAction){if(!lesson||busy)return;const id=lesson.id;busy=true;error="";try{const result=await localCourseRequest<CourseActionResult>(`/course/${id}/actions`,{method:"POST",body:JSON.stringify(action)});records=[...records.filter(p=>p.lesson_id!==id),result.progress];if(lesson?.id!==id)return;progress=result.progress;if("exerciseId"in action&&result.feedback)feedback={...feedback,[action.exerciseId]:result.feedback};return result;}catch(e){error=e instanceof Error?e.message:"Progress could not be saved.";}finally{busy=false;}}
async function changePane(next:typeof pane){inspector="";const result=await act({type:"navigate",step:next==="practice"?"practice":next==="pattern"?"grammar":"read"});if(result){pane=next;if(next==="pattern")support();savePosition();}}
async function inspect(id:string,type:"vocabulary"|"grammar"){if(!document.activeElement?.closest(".inspector"))referenceTrigger=document.activeElement as HTMLElement;support();inspector=id;await tick();referenceClose?.focus({preventScroll:true});await act({type:"encounter",itemType:type,targetId:id});}
function openReview(lessonId:string,id:string){requestedExercise=id;go(lessonId);}
function exportRecords(){const data:Record<string,unknown>={};for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i)!;if(key.startsWith(localPrefix))data[key]=JSON.parse(localStorage.getItem(key)!);}const blob=new Blob([JSON.stringify({format:"langouste-browser-progress-v1",exportedAt:new Date().toISOString(),records:data},null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="langouste-progress.json";a.click();URL.revokeObjectURL(url);notice="Progress exported. Keep this file before clearing browser data or changing domains.";}
</script>

{#snippet sentence(item:CourseSentence,alwaysEnglish=false)}
{@const sentenceLanguage=lesson?.language??language}
{@const parts=courseSentenceParts(item,sentenceLanguage)}
<div class="sentence">
<p class="target" lang={language} dir={arabic?"rtl":"ltr"}>{#each parts as part}{@const annotated=courseReadingSupport(part,sentenceLanguage)}<DictionaryText text={part.text} language={sentenceLanguage} filoDoc={annotated.doc} sentenceSupport={annotated.support} onSupportUsed={support} onOpenDictionary={openReadingDictionary}/>{/each}</p>
<CourseAudio {language} text={item.text} hideMissing/>
{#if arabic&&transliteration&&item.transliteration}<p class="transliteration" dir="ltr">{item.transliteration}</p>{/if}
{#if alwaysEnglish||translations.includes(item.id)}<p class="translation" lang="en" dir="ltr">{item.english}</p>{/if}
{#if !alwaysEnglish}<button class="sentence-reveal" aria-expanded={translations.includes(item.id)} onclick={()=>reveal(item.id)}>{translations.includes(item.id)?"Hide meaning":"Show meaning"}</button>{/if}
</div>
{/snippet}

<svelte:window onkeydown={e=>{if(e.key==="Escape"){if(inspector)closeReference();mobileIndex=false;}}}/>
<div class="workbook">
<a class="skip" href="#study-content" onclick={e=>{e.preventDefault();document.getElementById("study-content")?.focus();}}>Skip to study</a>
<header class="app-header"><button class="brand" onclick={()=>go()}>Langouste</button><div class="languages" aria-label="Course language">{#each ["hu","ar-EG"] as l}<button aria-pressed={language===l} onclick={()=>switchLanguage(l as CourseLanguage)}>{label(l as CourseLanguage)}</button>{/each}</div><select class="mobile-language" aria-label="Course language" value={language} onchange={e=>switchLanguage(e.currentTarget.value as CourseLanguage)}><option value="hu">Hungarian</option><option value="ar-EG">Egyptian Arabic</option></select><span class="storage-label">Browser-local progress</span><button class="index-toggle" aria-expanded={mobileIndex} onclick={()=>mobileIndex=!mobileIndex}>Lessons</button></header>
<div class="workspace" class:with-inspector={!!inspector&&!!lesson}>
<aside class="index" class:mobile-open={mobileIndex} aria-label="Course navigation">
<nav class="destinations" aria-label="Study destinations">{#each [["","Lessons"],["review","Review"],["reference","Reference"],["settings","Settings"]] as [id,title]}<button class:current={destination===(id||"lessons")} onclick={()=>go(id)}>{title}{#if id==="review"&&difficult.length}<span>{difficult.length}</span>{/if}</button>{/each}</nav>
<div class="index-caption">{label(language)} <span>30 days + supplements</span></div>
<ol class="lesson-list">{#each lessons as item}{@const state=records.find(p=>p.lesson_id===item.id)}<li><button aria-current={selected===item.id?"page":undefined} onclick={()=>go(item.id)}><span class="day-number">{item.day<=30?String(item.day).padStart(2,"0"):"+"}</span><span>{item.title}{#if state}<small>{state.completed_at?"Activities completed":"In progress"}</small>{/if}</span></button></li>{/each}</ol>
</aside>
<main id="study-content" tabindex="-1">
{#if error}<div class="error" role="alert">{error} <button onclick={()=>location.reload()}>Retry</button></div>{/if}
{#if notice}<p class="notice" role="status">{notice}</p>{/if}
{#if loading}<p role="status">Loading lessons…</p>
{:else if destination==="settings"}
<h1>Saved progress</h1><section class="prose"><p>Progress is saved only in this browser. Export a backup before clearing site data or changing devices.</p><button class="primary" onclick={()=>{try{exportRecords();}catch{error="Could not export progress. Your saved records are unchanged.";}}}>Export progress</button></section>
{:else if destination==="review"}
<h1>Review difficult items</h1>{#if difficult.length}<ol class="review-list">{#each difficult as item}<li><button onclick={()=>openReview(item.lessonId,item.id)}><strong>{item.title}</strong><span>Question {item.id.split("-").at(-1)} · last tried {new Date(item.at).toLocaleDateString()}</span></button></li>{/each}</ol>{:else}<p class="empty">No questions to review.</p><button class="primary" onclick={()=>go(resume[language]??lessons[0]?.id)}>Open a lesson</button>{/if}
{:else if destination==="reference"}
<h1>Words & phrases</h1><label class="search-label">Find a word, meaning or transliteration<input type="search" bind:value={search}/></label>{#if referenceLoading}<p role="status">Loading reference…</p>{:else}<p class="muted">{referenceWords.length} entries</p><div class="reference-list">{#each referenceWords as entry}<details><summary><bdi lang={language}>{entry.term}</bdi><span>{entry.english}</span></summary><p>{entry.transliteration??""}</p>{#if entry.teachingNote}<p>{entry.teachingNote}</p>{/if}<p lang={language} dir={arabic?"rtl":"ltr"}>{entry.example.text}</p><p>{entry.example.english}</p><button onclick={()=>go(entry.lessonId)}>Open lesson</button></details>{/each}</div>{/if}
{:else if !lesson&&!selected}
<div class="index-title"><h1>{label(language)}</h1><button class="primary" onclick={()=>go(resume[language]??lessons[0]?.id)}>{resume[language]?"Resume lesson":"Start day 1"}</button></div>

<div class="syllabus">{#each lessons as item}{@const state=records.find(p=>p.lesson_id===item.id)}<button class="syllabus-row" onclick={()=>go(item.id)}><span class="day-number">{item.day<=30?String(item.day).padStart(2,"0"):"+"}</span><span><strong>{item.title}</strong><small>{item.day>30?"Daily supplement · ":""}{item.estimatedMinutes} min · {item.exerciseCount} questions</small></span><span class="activity">{state?.completed_at?"Completed":state?"Continue":"Open"}</span></button>{/each}</div>
{:else if lesson&&progress&&lesson.language===language}
<div class="lesson-heading"><h1>{lesson.title}</h1><p class="lesson-meta">{lesson.day<=30?`Day ${lesson.day}`:"Daily supplement"} · {label(language)} · {lesson.estimatedMinutes} min</p></div>
<nav class="lesson-tabs" aria-label="Lesson sections">{#each [["read","Read"],["pattern","Notice a pattern"],["practice","Practise"],["reread","Reread"]] as [id,title]}<button aria-current={pane===id?"step":undefined} disabled={busy} onclick={()=>changePane(id as typeof pane)}>{title}</button>{/each}</nav>
<div class="save-status" role="status">{busy?"Saving…":"Saved in this browser"}</div>
{#if pane==="practice"}
{#key lesson.id}<StudyPractice {lesson} {progress} {feedback} {busy} {act} {inspected} onSupportUsed={support} onPosition={savePosition} startIndex={practiceStart}/>{/key}
<details class="activity-record"><summary>Progress</summary><p>{progress.read_sections.length} of {lesson.readings.length} readings acknowledged. {completedExercises} of {lesson.exercises.length} questions attempted.</p><button class="primary" disabled={busy||!!progress.completed_at||progress.read_sections.length!==lesson.readings.length||completedExercises!==lesson.exercises.length} onclick={()=>act({type:"complete"})}>{progress.completed_at?"Activities completed":"Mark activities complete"}</button></details>
{:else if pane==="pattern"}
<h2>Notice how it works</h2>{#each lesson.concepts as pattern}<section class="pattern"><h3>{pattern.title}</h3><p>{pattern.explanation}</p>{#each pattern.examples as example}{@render sentence(example,true)}{/each}<button onclick={()=>inspect(pattern.id,"grammar")}>Keep this pattern open</button></section>{/each}<button class="primary" onclick={()=>{support();changePane("practice");}}>Try the exercises</button>
{:else}
{#if pane==="read"}<details class="orientation" ontoggle={e=>{if(e.currentTarget.open)support();}}><summary>Language notes</summary>{#each lesson.instructionBlocks??[] as block}<h3>{block.title}</h3><p>{block.body}</p>{#each block.examples??[] as example}{@render sentence(example)}{/each}{/each}</details>{:else}{/if}
<div class="reading-tools"><label>Passage <select aria-label="Reading passage" value={section} onchange={e=>{section=Number(e.currentTarget.value);savePosition();}}>{#each lesson.readings as r,i}<option value={i}>{i+1}. {r.title}</option>{/each}</select></label>{#if arabic}<label><input type="checkbox" checked={transliteration} onchange={e=>{transliteration=e.currentTarget.checked;if(transliteration)support();}}/> Transliteration</label>{/if}</div>
{#if reading}<article class="reading" aria-label={reading.title}>{#if reading.instruction}<details class="reading-note" ontoggle={e=>{if(e.currentTarget.open)support();}}><summary>Reading note</summary><p>{reading.instruction}</p></details>{/if}{#each reading.sentences as item}{@render sentence(item)}{/each}
{#if reading.recognitionOnly?.length}<details class="recognition"><summary>More phrases</summary>{#each reading.recognitionOnly as item}{@render sentence(item)}{/each}</details>{/if}
<div class="reading-actions"><button disabled={busy||progress.read_sections.includes(reading.id)} onclick={()=>act({type:"read",sectionId:reading!.id,englishVisible:reading!.sentences.some(s=>translations.includes(s.id)),transliterationVisible:transliteration})}>{progress.read_sections.includes(reading.id)?"Reading acknowledged":"I’ve read this passage"}</button>{#if section<lesson.readings.length-1}<button onclick={()=>{section++;savePosition();}}>Next passage</button>{:else}<button class="primary" onclick={()=>changePane("pattern")}>Notice a pattern</button>{/if}</div></article>{/if}
<section class="word-strip"><h2>Words & phrases in this lesson</h2><div>{#each lesson.vocabulary as entry}<button class:open={inspector===entry.id} onclick={()=>inspect(entry.id,"vocabulary")}><bdi lang={language}>{entry.term}</bdi></button>{/each}</div></section>
{#if lesson.optionalDialogue?.length}<details class="dialogue"><summary>Conversation</summary>{#each lesson.optionalDialogue as item}{@render sentence(item)}{/each}</details>{/if}
{#if lesson.review}<details class="dialogue"><summary>Try it</summary><ul>{#each lesson.review.prompts as prompt}<li>{prompt}</li>{/each}</ul></details>{/if}
{/if}
<details class="lesson-context"><summary>Sources</summary>{#each lesson.sources as source}<article><h3><a href={source.url} target="_blank" rel="noreferrer">{source.title}</a></h3><p>{source.publisher} · {source.publishedOn??"Undated"}</p><details><summary>Details</summary><p>{source.factSummary}</p></details></article>{/each}</details>
{/if}
</main>
{#if inspector&&lesson}<aside class="inspector" aria-label="Language reference"><div class="inspector-header"><button bind:this={referenceClose} aria-label="Close reference" onclick={closeReference}>Close</button></div>{#if inspector==="dictionary"&&dictionaryEntry}<DictionaryPopover inline resources={false} term={dictionaryEntry.term} headword={dictionaryEntry.headword} lookup={dictionaryEntry.lookup} contextMeaning={dictionaryEntry.contextMeaning} {language} languageLabel={label(language)} anchor={null}/>{:else if word}<h3 lang={language} dir={arabic?"rtl":"ltr"}>{word.term}</h3><CourseAudio {language} text={word.term} context={word.semanticConcept??""} hideMissing/>{#if word.transliteration}<p dir="ltr">{word.transliteration}</p>{/if}<p class="meaning">{word.english}</p>{#if word.teachingNote}<p>{word.teachingNote}</p>{/if}<h4>In a sentence</h4>{@render sentence(word.example,true)}{#if word.forms?.length}<h4>Authored forms</h4>{#each word.forms as form}<p><bdi>{form.arabic??form.term}</bdi> {form.transliteration??""} · {form.english??""}</p>{/each}{/if}{:else if concept}<h3>{concept.title}</h3><p>{concept.explanation}</p>{#each concept.examples as example}{@render sentence(example,true)}{/each}{/if}</aside>{/if}
</div>
</div>
<style>
@font-face{font-family:"Source Serif 4";src:url("../assets/source-serif4.ttf") format("truetype");font-style:normal;font-weight:200 900;font-display:swap}

.workbook{flex:1 0 auto;--ink:#24352c;--muted:#526057;--accent:#245c44;--line:#d4dad2;min-height:100%;color:var(--ink);background:#fcfcf8;font-size:16px;line-height:1.55;--color-accent:#245c44;--color-accent-contrast:#fff;caret-color:var(--accent);scrollbar-color:#9ba99e #f3f4ee}.workbook :global(::selection){background:#cde2d2;color:#183725}.workbook :global(button),.workbook :global(input),.workbook :global(select),.workbook :global(textarea){font-family:inherit}.app-header{height:64px;display:flex;align-items:center;gap:24px;padding:0 24px;border-bottom:1px solid var(--line);background:#fcfcf8;position:sticky;top:0;z-index:5}.brand{font-family:"Source Serif 4",Georgia,serif;font-size:25px;font-weight:600;background:none;border:0;color:var(--ink);padding:0;min-height:44px}.languages{display:flex;gap:4px}.languages button{border:0;background:transparent;color:var(--muted);font-size:16px;padding:8px 12px;min-height:44px}.languages [aria-pressed=true]{background:#e7eee5;color:#19472f;border-radius:3px}.storage-label{margin-left:auto;color:var(--muted);font-size:13px}.workspace{display:grid;grid-template-columns:236px minmax(0,1fr);min-height:calc(100vh - 64px)}.workspace.with-inspector{grid-template-columns:236px minmax(0,1fr)}.index{border-right:1px solid var(--line);background:#f2f4ed;padding:16px 12px;position:sticky;top:64px;height:calc(100vh - 64px);overflow:auto}.destinations{display:grid;grid-template-columns:1fr 1fr;gap:4px;padding-bottom:16px;border-bottom:1px solid var(--line)}.destinations button{font-size:15px;text-align:left;padding:8px;background:transparent;border:0;min-height:44px;color:var(--muted)}.destinations .current{color:#19472f;background:#e0e8dc;font-weight:600;border-radius:3px}.destinations span{margin-left:6px;font-size:12px}.index-caption{font-size:14px;font-weight:600;padding:16px 8px 10px}.index-caption span{display:block;font-size:12px;font-weight:400;color:var(--muted)}.lesson-list{list-style:none}.lesson-list button{width:100%;displa